record_usage:
def record_usage(state, key, model, tokens) do
  if not (is_binary(key) and key != ""), do: raise("key must be a non-empty string")
  if not (is_binary(model) and model != ""), do: raise("model must be a non-empty string")
  if not (is_integer(tokens) and tokens > 0), do: raise("tokens must be a positive whole number")
  quota = quota_of(state, key)
  if quota != nil and usage(state, key) + tokens > quota, do: raise("call would exceed the key's quota")
  calls = Map.get(state, "calls", [])
  call = %{"key" => key, "model" => model, "tokens" => tokens}
  new_state = Map.put(state, "calls", calls ++ [call])
  {usage(new_state, key), new_state}
end

set_price:
def set_price(state, model, cents_per_1k_tokens) do
  if not (is_binary(model) and model != ""), do: raise("model must be a non-empty string")
  if not (is_number(cents_per_1k_tokens) and cents_per_1k_tokens >= 0), do: raise("price must be a non-negative number of cents per 1000 tokens")
  prices = Map.get(state, "prices", %{})
  {cents_per_1k_tokens, Map.put(state, "prices", Map.put(prices, model, cents_per_1k_tokens))}
end

set_quota:
def set_quota(state, key, tokens) do
  if not (is_binary(key) and key != ""), do: raise("key must be a non-empty string")
  if not (is_integer(tokens) and tokens >= 0), do: raise("quota must be a non-negative integer")
  if usage(state, key) > tokens, do: raise("key has already used more than that quota")
  quotas = Map.get(state, "quotas", %{})
  {tokens, Map.put(state, "quotas", Map.put(quotas, key, tokens))}
end
